{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Viqualine, the closest retrieved analogue (Morgan 0.4079), has an absolute oral bioavailability of about 80% in healthy subjects after a 25 mg tablet versus IV; its shared 6-methoxyquinoline and vinyl-substituted saturated azacycle makes this the strongest transferable evidence for high F in the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alizapride, a basic amine with an N-allyl piperidine and a methoxy-substituted heteroaromatic, showed 89.7% systemic availability after oral dosing in humans, supporting high F for the query's basic amine/methoxyheteroarene combination.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Lenvatinib, which contains a methoxyquinoline core, has an absolute bioavailability of about 85% in humans, providing additional lower-transfer support for high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Tegaserod, a methoxyindole with a basic guanidine, has only about 10% absolute bioavailability in humans; this is the main low-F evidence, but its low Morgan similarity and different polar/ionizable functionality limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable evidence, viqualine, shows high absolute oral bioavailability (~80%) in humans, and other methoxyquinoline/basic-amine drugs (lenvatinib, alizapride) also show high F. Low-F compounds such as tegaserod are structurally distant and do not outweigh this. Therefore predict high (F >= 20%).",
  "evidence_gaps": [
    "No direct experimental F measurement for the exact query molecule.",
    "The closest analogue (viqualine) has only moderate Morgan similarity (0.41) and differs by a bridged tertiary amine and a benzylic hydroxyl versus a secondary piperidine and propyl linker.",
    "Low-F evidence from tegaserod and melatonin is structurally distant and does not establish a mechanism applicable to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

